const $=s=>document.querySelector(s),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','panels.js','deck-midi.js','midi.js','stems.js','pitchplay.js','midi-stems-pitch-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f)).arrayBuffer())])));
async function until(fn,label,ms=12000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
const click=s=>{assert($(s),'Missing '+s);$(s).click();},field=(s,v)=>{assert($(s),'Missing '+s);$(s).value=String(v);};
const button=(n,a)=>`[data-deck="${n}"][data-action="${a}"]`;
function add(target,ch,n){field('#midi-target',target);field('#midi-type','Note');field('#midi-channel',ch);field('#midi-number',n);field('#midi-encoding','7-bit absolute');click('#midi-add');}
function send(ch,n,value=127){field('#midi-type','Note');field('#midi-channel',ch);field('#midi-number',n);field('#midi-test-value',value);click('#midi-send');}
function press(ch,n){send(ch,n);send(ch,n,0);}
function base64(b){let s='';for(let i=0;i<b.length;i+=16384)s+=String.fromCharCode(...b.subarray(i,i+16384));return btoa(s);}
function measure(data,sr,from,to){let power=0;const crossings=[],start=Math.ceil(from*sr),end=Math.floor(to*sr);assert(start>=0&&end<=data.length&&end>start,'Invalid measurement window');for(let i=start;i<end;i++){power+=data[i]**2;if(i>start&&data[i-1]<0&&data[i]>=0)crossings.push((i-1-data[i-1]/(data[i]-data[i-1]))/sr);}return{from,to,rms:Math.sqrt(power/(end-start)),hz:crossings.length>3?(crossings.length-1)/(crossings.at(-1)-crossings[0]):null};}
let app;
async function run(){
 $('#stempitch-run').disabled=true;const {engine,state}=app,d=state.decks[0],pitch=state.decks[1];
 const report={startedAt:new Date().toISOString(),completed:false,scope:'Actual app MIDI editor with synthetic messages, prepared known stem fixtures and original master recording. No fresh model-separation, full FX/pitch-quality, native or physical controller acceptance.',criteria:{frequencyErrorHz:1.5,playingMinimumRMS:.005,silentMaximumRMS:.0001,selectedCuePositionToleranceSeconds:.01},events:[],checks:[],errors:[]};
 const event=name=>{const e={name,time:engine.ctx.currentTime-engine.recordStarted};report.events.push(e);return e;};
 try{
  report.sourceBefore=await identities();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical mute');await until(()=>!state.analysis,'Initial analysis');
  const sr=engine.ctx.sampleRate,duration=12,frequencies=[220,330,440,660],make=(channel,freq,amplitude)=>{const b=engine.ctx.createBuffer(2,sr*duration,sr),a=b.getChannelData(channel);for(let i=0;i<a.length;i++)a[i]=amplitude*Math.sin(2*Math.PI*freq*i/sr);return b;},stems=frequencies.map(f=>make(0,f,.03)),original=engine.ctx.createBuffer(2,sr*duration,sr);
  for(const b of stems){const a=original.getChannelData(0),v=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]+=v[i];}
  for(const deck of [d,pitch]){Object.assign(deck.track,{bpm:120,grid:0,gridWarpMarkers:[],duration,analyzed:true,sampleGain:0,cues:Array(8).fill(null)});Object.assign(deck,{rate:1,position:0,keylock:false,keyShift:0,reverse:false,loop:false,stemSlip:'off',slip:false,sync:false,level:.8,stems:[true,true,true,true],stemFX:[false,false,false,false],pitchRangeMode:'Middle',pitchCue:0});engine.clearDeckScratchCache(deck.index);engine.mix(deck.index,'level',.8);}
  engine.buffers.set(d.track.id,original);engine.stemBuffers.set(d.track.id,stems);engine.buffers.set(pitch.track.id,make(1,550,.12));await engine.seek(d,.2);await engine.seek(pitch,.2);
  click('[data-panel="midi"]');click('#midi-reset');for(let n=0;n<8;n++)add(`Deck 1 stems pad ${n+1}`,7,32+n);add('Deck 2 pitch play pad 2',8,65);add('Deck 2 pitch cue select pad 2',8,73);
  click('#modal-close');click(button(0,'play'));click(button(1,'play'));await until(()=>d.playing&&pitch.playing,'Two real decks');click('[data-panel="midi"]');await engine.recordStart();event('record-start');await sleep(200);
  for(let n=0;n<4;n++)press(7,32+n);await until(()=>d.stems.every(v=>!v),'All Stem toggles off');const muted=event('all-stems-muted');await sleep(300);
  press(7,32);await until(()=>d.stems[0]&&!d.stems.slice(1).some(Boolean),'Vocal only');const vocal=event('vocal-only');await sleep(350);
  for(let n=4;n<8;n++)press(7,32+n);await until(()=>d.stemFX.every(Boolean),'Four Stem FX actions');await until(()=>engine.stemStates.get(0)?.effects[0],'Real vocal Echo effect');report.stems={enabled:[...d.stems],effectsEnabled:[...d.stemFX],actualModes:[...engine.stemStates.get(0).modes],actualVocalEffect:!!engine.stemStates.get(0).effects[0]};await sleep(200);for(let n=4;n<8;n++)press(7,32+n);await until(()=>d.stemFX.every(v=>!v),'FX off');
  click('#modal-close');click(button(1,'play'));await until(()=>!pitch.playing,'Pause Pitch deck');await engine.seek(pitch,1.23);click('[data-panel="midi"]');press(8,73);await until(()=>pitch.pitchCue===1&&pitch.track.cues[1],'Shift cue selection');report.selection={cue:pitch.pitchCue,position:pitch.track.cues[1].position,playing:pitch.playing,keyShift:pitch.keyShift};assert(!pitch.playing&&pitch.keyShift===0,'Shift cue selection played or pitched audio');
  send(8,65);await until(()=>pitch.playing&&!pitch.processing,'Held Pitch audition',25000);report.pitch={shift:pitch.keyShift,keylock:pitch.keylock,position:engine.position(pitch),cue:1};assert(pitch.keyShift===1&&pitch.keylock,'Pitch pad did not apply Middle+1');await sleep(400);const shifted=event('pitch-held-plus-one');await sleep(250);
  const mapping=state.mappings.findIndex(m=>m.target==='Deck 2 pitch play pad 2');click(`[data-midi-remove="${mapping}"]`);send(8,65,0);await until(()=>!pitch.playing&&!pitch.processing,'Pitch Note Off after mapping removal');report.release={playing:pitch.playing,position:engine.position(pitch)};assert(Math.abs(report.release.position-report.selection.position)<.01,'Pitch release lost selected cue');const released=event('pitch-released');await sleep(300);click('#modal-close');
  const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};const decoded=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));report.decoded={duration:decoded.duration,sampleRate:decoded.sampleRate,frames:decoded.length,channels:decoded.numberOfChannels};assert(decoded.numberOfChannels===2,'Expected stereo');for(let c=0;c<2;c++)for(const v of decoded.getChannelData(c))assert(Number.isFinite(v),'Nonfinite PCM');
  report.audio=[['muted',muted,[null,550]],['vocal',vocal,[220,550]],['pitch-held',shifted,[220,550*2**(1/12)]],['pitch-release',released,[220,null]]].map(([name,e,expected])=>({name,expected,channels:[0,1].map(c=>measure(decoded.getChannelData(c),decoded.sampleRate,e.time+.08,e.time+.22))}));for(const w of report.audio)w.channels.forEach((m,c)=>{if(w.expected[c]===null)assert(m.rms<.0001,w.name+' expected silence');else assert(m.rms>.005&&Math.abs(m.hz-w.expected[c])<1.5,w.name+' expected carrier');});
  report.checks=['All four actual Stem mutes and restore reach real master audio','All four Stem FX flags reach updateStems and actual vocal Echo owner','Shift cue selection creates/selects cue without playback or pitch change','Held Pitch Play shifts real audio and original release survives mapping deletion'];
 }catch(error){report.errors.push({message:error.message,stack:error.stack});}
 finally{
  for(const deck of state.decks)engine.pause(deck);if(engine.recording){const blob=await engine.recordStop();if(blob){const bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};}}report.sourceAfter=await identities();report.sourceStable=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.completed=report.checks.length===4&&!report.errors.length&&report.sourceStable;report.finishedAt=new Date().toISOString();$('#stempitch-original').textContent=JSON.stringify(report,null,2);$('#stempitch-results').textContent=JSON.stringify({...report,recording:report.recording?{...report.recording,base64:'Retained in original JSON'}:null},null,2);$('#stempitch-status').textContent=report.completed?'Scoped Stems/Pitch workflow passed; audio stopped':'Failed: '+report.errors.map(e=>e.message).join('; ');
 }
}
$('#stempitch-run').onclick=()=>run();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#stempitch-run').disabled=false;$('#stempitch-run').textContent='Run one Stems/Pitch workflow';}
boot().catch(error=>$('#stempitch-status').textContent=error.message);
